import java.util.*;
import java.io.*;

public class Main {
    static class FlowNetwork {
        int size;
        List<int[]> edgesList;
        List<List<Edge>> adjList;
        int[] potential;
        int[] prevNode;
        int[] prevEdge;

        public FlowNetwork(int size) {
            this.size = size;
            this.edgesList = new ArrayList<>();
            this.adjList = new ArrayList<>();
            for (int i = 0; i < size; i++) {
                adjList.add(new ArrayList<>());
            }
        }

        class Edge {
            int to, rev, cap, cst;

            public Edge(int to, int rev, int cap, int cst) {
                this.to = to;
                this.rev = rev;
                this.cap = cap;
                this.cst = cst;
            }
        }

        public int addEdge(int u, int v, int capacity, int cost) {
            int idx = edgesList.size();
            edgesList.add(new int[]{u, adjList.get(u).size()});
            adjList.get(u).add(new Edge(v, adjList.get(v).size(), capacity, cost));
            adjList.get(v).add(new Edge(u, adjList.get(u).size() - 1, 0, -cost));
            return idx;
        }

        public Edge getEdge(int i) {
            int[] e = edgesList.get(i);
            Edge edge = adjList.get(e[0]).get(e[1]);
            Edge re = adjList.get(edge.to).get(edge.rev);
            return new Edge(e[0], edge.to, edge.cap + re.cap, edge.cst);
        }

        public List<Edge> allEdges() {
            List<Edge> result = new ArrayList<>();
            for (int i = 0; i < edgesList.size(); i++) {
                int[] e = edgesList.get(i);
                Edge edge = adjList.get(e[0]).get(e[1]);
                Edge re = adjList.get(edge.to).get(edge.rev);
                result.add(new Edge(e[0], edge.to, edge.cap + re.cap, edge.cst));
            }
            return result;
        }

        private boolean dijkstra(int s, int t, int[] prevNode, int[] prevEdge, int[] dist, boolean[] visited) {
            Arrays.fill(dist, Integer.MAX_VALUE);
            Arrays.fill(prevNode, -1);
            Arrays.fill(prevEdge, -1);
            Arrays.fill(visited, false);
            PriorityQueue<int[]> heap = new PriorityQueue<>(Comparator.comparingInt(a -> a[0]));
            dist[s] = 0;
            heap.offer(new int[]{0, s});
            while (!heap.isEmpty()) {
                int[] current = heap.poll();
                int d = current[0];
                int v = current[1];
                if (visited[v]) continue;
                visited[v] = true;
                if (v == t) break;
                for (int i = 0; i < adjList.get(v).size(); i++) {
                    Edge e = adjList.get(v).get(i);
                    if (visited[e.to] || e.cap == 0) continue;
                    int nd = d + e.cst;
                    if (dist[e.to] > nd) {
                        dist[e.to] = nd;
                        prevNode[e.to] = v;
                        prevEdge[e.to] = i;
                        heap.offer(new int[]{nd, e.to});
                    }
                }
            }
            return visited[t];
        }

        public List<int[]> minCostMaxFlow(int s, int t, long maxFlow) {
            long flow = 0;
            long totalCost = 0;
            List<int[]> results = new ArrayList<>();
            results.add(new int[]{(int) flow, (int) totalCost});
            this.potential = new int[size];
            this.prevNode = new int[size];
            this.prevEdge = new int[size];
            int[] dist = new int[size];
            boolean[] visited = new boolean[size];

            while (flow < maxFlow) {
                boolean foundPath = dijkstra(s, t, prevNode, prevEdge, dist, visited);
                if (!foundPath) break;
                long c = maxFlow - flow;
                int v = t;
                while (v != s) {
                    int u = prevNode[v];
                    Edge e = adjList.get(u).get(prevEdge[v]);
                    c = Math.min(c, e.cap);
                    v = u;
                }
                v = t;
                while (v != s) {
                    int u = prevNode[v];
                    Edge e = adjList.get(u).get(prevEdge[v]);
                    e.cap -= c;
                    adjList.get(e.to).get(e.rev).cap += c;
                    v = u;
                }
                int delta = -potential[s];
                flow += c;
                totalCost += c * delta;
                if (results.get(results.size() - 1)[1] == totalCost) {
                    results.remove(results.size() - 1);
                }
                results.add(new int[]{(int) flow, (int) totalCost});
            }
            return results;
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] data = br.readLine().split(" ");
        int n = Integer.parseInt(data[0]);
        data = br.readLine().split(" ");
        int a1 = Integer.parseInt(data[0]);
        int a2 = Integer.parseInt(data[1]);
        int a3 = Integer.parseInt(data[2]);
        data = br.readLine().split(" ");
        int b1 = Integer.parseInt(data[0]);
        int b2 = Integer.parseInt(data[1]);
        int b3 = Integer.parseInt(data[2]);

        FlowNetwork g = new FlowNetwork(8);
        g.addEdge(0, 1, a1, 0);
        g.addEdge(0, 2, a2, 0);
        g.addEdge(0, 3, a3, 0);
        g.addEdge(4, 7, b1, 0);
        g.addEdge(5, 7, b2, 0);
        g.addEdge(6, 7, b3, 0);

        for (int i = 1; i <= 3; i++) {
            for (int j = 4; j <= 6; j++) {
                int cst = ((j - i) % 3 == 1) ? 1 : 0;
                g.addEdge(i, j, Integer.MAX_VALUE, cst);
            }
        }

        List<int[]> res = g.minCostMaxFlow(0, 7, (long) Math.pow(2, 32) - 1);
        int ans1 = res.get(res.size() - 1)[0];
        int ans2 = Math.min(a1, b2) + Math.min(a2, b3) + Math.min(a3, b1);
        System.out.println(ans1 + " " + ans2);
    }
}
